   "sector": "economia",
   "titulo": "MEF insistirá en mover feriados al lunes, ¿qué falta para concretar la medida?",
   "resumen": "El ministro de Economía y Finanzas, Elmer Cuba, señaló que el Gobierno busca modificar la distribución de los feriados nacionales a partir del próximo año.",
   "fuente": "Gestión",
   "url": "https://gestion.pe/peru/politica/mef-insistira-en-mover-feriados-al-lunes-que-falta-para-concretar-la-medida-noticia/",
   "fecha": "2026-11-07T15:22:00Z",
   "tipo": "comercial",
   "ambito": "peru",
   "genero": "noticia",
   "imagen": "https://gestion.pe/resizer/v2/HJF3WFVPBNE6HFM6QGIIV4KGFU.jpg?auth=8106a697e04bea358570464772e971d1c1bc75626a014a7c0c5d95c364b77f7e&smart=true&width=2000&height=1333",
   "procedencia": "directa",
   "sintesis": "El ministro de Economía y Finanzas, Elmer Cuba, señaló que el Gobierno busca modificar la distribución de los feriados nacionales a partir del próximo año. “Lo que se ha decidido es el próximo año moverlos a los lunes.",
   "puntos": [
    "El ministro de Economía y Finanzas, Elmer Cuba, señaló que el Gobierno busca modificar la distribución de los feriados nacionales a partir del próximo año.",
    "“Lo que se ha decidido es el próximo año moverlos a los lunes.",
    "Cualquier feriado que caiga entre martes y viernes se mueve para el lunes más cercano, para que no hagan tanto daño como un feriado a media semana” , indicó Cuba durante una entrevista con RPP Noticias."
   ]
